from __future__ import annotations
import functools
import logging
import random
import shlex
import string
import time
from pathlib import Path

from .exception import ExhaustedNumberOfAttemptsError

logger = logging.getLogger(__name__)


def generate_random_string(length=30):
    """Generate a random string of a specific length."""
    return ''.join(random.choices(string.ascii_uppercase + string.digits, k=length))


def retry(attempts: int, delay: int = 0) -> callable:
    def decorator(method):
        @functools.wraps(method)
        def wrapper(*args, **kwargs):
            for attempt in range(attempts):
                try:
                    return method(*args, **kwargs)
                except Exception as e:
                    logger.warning(e)
                    logger.warning(f"Attempt no. {attempt+1} failed. Retrying.")
                    if delay:
                        time.sleep(delay)
            raise ExhaustedNumberOfAttemptsError(
                f"Method {method.__name__} failed after {attempts} attempts."
            )
        return wrapper
    return decorator


def sh_quote(path: str | Path) -> str:
    """
    >>> sh_quote("/tmp/file_organizer.tar.gz")
    "/tmp/file_organizer.tar.gz"
    >>> sh_quote("/home/ute/logs/SYSLOG*.log")
    "/home/ute/logs/SYSLOG*.log"
    >>> sh_quote("/home/ute/logs dir/SYSLOG*.log")
    "'/home/ute/logs dir/SYSLOG'*.log"
    >>> sh_quote("/home/ute/result_1_322dev/ENB_syslog_*")
    "/home/ute/result_1_322dev/ENB_syslog_*"
    >>> sh_quote("/home/ute/[1][1]automation result/ENB_syslog_*")
    "'/home/ute/[1][1]automation result/ENB_syslog_'*"
    """
    path = str(path)
    assert path.count("*") <= 1, f"Only one wildcard '*' can be used in a path:\n{path}"

    if "*" in path:
        parts = list(path.rpartition("*"))
        parts[0] = shlex.quote(parts[0])
        if not parts[-1]:
            return f"{parts[0]}*"
        return "".join(parts)
    return shlex.quote(path)
